************************************************************************ Integer Math Tool Patch** Copyright (C)   1989, 1992* Apple Computer, Inc.* All Rights Reserved.************************************************************************* REVISION HISTORY** xx-xxx-89** This file contains the call table for the integer math routines* Only one routine is being patched:  Long2Dec.** 5-Feb-92	Dave Lyons** Version $0300 for 6.0 final.************************************************************************* 5-Mar-92	Dave Lyons** Version $8301 for 6.0.1d2.** Patch Int2Dec and Long2Dec:  If stringPtr bit 31 is set and the* buffer length is at least 5, return zero as "zero " instead of* blanks followed by a "0".** 2-Apr-93 DAL** Version $0301 for 6.0.1.***********************************************************************IntMathVersion	equ $0301************************************************************************ CALL TABLE***********************************************************************IMCallTable	PROC EXPORT	import Long2DecPatch,Int2DecPatch	import IMVersion	DC.L (TheEnd-IMCallTable)/4	DC.L 0     ;  oEndCall0-1	;power up init	DC.L 0     ;  oEndCall0-1	;application startup	DC.L 0     ;  oEndCall0-1	;application shutdown	DC.L IMVersion-1	DC.L 0     ;  oEndCall0-1	;reset	DC.L 0     ;  IMActive-1	DC.L 0     ;  oEndCall0-1	;reserved	DC.L 0     ;  oEndCall0-1	;reserved	DC.L 0     ;  Multiply-1	DC.L 0     ;  SDivide-1	DC.L 0     ;  UDivide-1	DC.L 0     ;  LongMul-1	DC.L 0     ;  LongDiv-1	DC.L 0     ;  FixRatio-1	DC.L 0     ;  FixMul-1	DC.L 0     ;  FracMul-1	DC.L 0     ;  FixDiv-1	DC.L 0     ;  FracDiv-1	DC.L 0     ;  FixRound-1	DC.L 0     ;  FracSqrt-1	DC.L 0     ;  FracCos-1	DC.L 0     ;  FracSin-1	DC.L 0     ;  FixATan2-1	DC.L 0     ;  HiWord-1	DC.L 0     ;  LoWord-1	DC.L 0     ;  Long2Fix-1	DC.L 0     ;  Fix2Long-1	DC.L 0     ;  Fix2Frac-1	DC.L 0     ;  Frac2Fix-1	DC.L 0     ;  Fix2X-1	DC.L 0     ;  Frac2X-1	DC.L 0     ;  X2Fix-1	DC.L 0     ;  X2Frac-1	DC.L 0     ;  Int2Hex-1	DC.L 0     ;  Long2Hex-1	DC.L 0     ;  Hex2Int-1	DC.L 0     ;  Hex2Long-1	DC.L Int2DecPatch-1		;patched 5-Mar-92 DAL	DC.L Long2DecPatch-1	DC.L 0     ;  Dec2Int-1	DC.L 0     ;  Dec2Long-1	DC.L 0     ;  HexIt-1TheEnd	ENDP************************************************************************ IMVersion***********************************************************************IMVersion	proc export	lda #IntMathVersion	sta 7,s	lda #0	clc	rtl	EndP************************************************************************ Int2DecPatch -- 5-Mar-92 DAL** Pre-patch the ROM to return "zero " if bit 31 of the string pointer* is set, the buffer length is at least 5, and the value is zero.***********************************************************************Int2DecPatch	procsignFlag	equ 7buffLen	equ 9stringPtr	equ 11value	equ 15	;word	lda value,s	bne @toROM	lda stringPtr+2,s	bpl @toROM	lda buffLen,s	cmp >theZeroStringLen	bcc @toROM	jsr StuffZeroString ;using stringPtr	jml >$feff96	;no error, strip 10 bytes@toROM	jml $fed04c	;old Int2Dec in ROM 1** StuffZeroString -- needs stringPtr and buffLen buried on stack*	export StuffZeroStringStuffZeroString	phd	tsc	tcd@buffLen	equ 13@stringPtr	equ 15	sep #$30	longa off	longi off	lda >theZeroStringLen	tax	;X counts backwards through source str	dex	ldy <@buffLen	;right-justify the "zero " in the field	dey@copy	lda >theZeroString,x	sta [<@stringPtr],y	dey	dex	bpl @copy; pad dest string with blanks	tya	bmi @done	lda #$20@padBlanks	sta [<@stringPtr],y	dey	bpl @padBlanks@done	rep #$30	longa on	longi on	pld	rts	export theZeroStringLen,theZeroStringtheZeroStringLen	dc.w 5theZeroString	dc.b 'zero '	dc.b '****'	;space for internationalizing	EndP************************************************************************ Long2DecPatch -- 5-Mar-92 DAL** Pre-patch the old patch to return "zero " if bit 31 of the string* pointer is set, the buffer length is at least 5, and the value is* zero.***********************************************************************Long2DecPatch	proc	import Long2Dec,StuffZeroString	import theZeroStringLen,theZeroStringsignFlag	equ 7buffLen	equ 9stringPtr	equ 11value	equ 15	;long	lda value,s	ora value+2,s	bne @oldWay	lda stringPtr+2,s	bpl @oldWay	lda buffLen,s	cmp >theZeroStringLen  ;long enough?	bcc @oldWay	jsr StuffZeroString ;using stringPtr	jml >$feffa1	;no error, strip 12 bytes@oldWay	brl Long2Dec	END